import { Component, inject, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { MoneyPipe } from '../currencies/money.pipe';
import { DashboardService } from './dashboard.service';
import { TaxAdjustments } from '../tax-adjustments/tax-adjustments';

// The tax charged over a chosen date range: the main (sales) tax and the levy, each totalled separately, on invoices
// issued within it that were sent (drafts and cancelled invoices are left out), in the home currency. Their sum is
// the tax collected; netted with the manual tax adjustments dated within the period it gives the tax liability: what
// is owed on to the tax authority.
@Component({
  selector: 'app-tax-summary',
  imports: [MoneyPipe, TaxAdjustments],
  styles: `
    .tax-summary-range {
      </form>
      @if (rangeError()) {
        <p role="alert" data-testid="tax-summary-range-error">{{ rangeError() }}</p>
      } @else if (summary.error()) {
        <p role="alert" data-testid="tax-summary-error">Could not load the tax summary.</p>
      } @else if (summary.value(); as t) {
        <dl class="tax-summary-figures" aria-live="polite">
          <dt>Invoices</dt>
          <dd data-testid="tax-summary-invoices">{{ t.invoices }}</dd>
          <dt>Main tax</dt>
          <dd data-testid="tax-summary-tax">
            <span data-testid="tax-summary-primary">{{ t.tax | money: t.homeCurrency }}</span>
          </dd>
          <dt>Levy</dt>
          <dd data-testid="tax-summary-levy">{{ t.levy | money: t.homeCurrency }}</dd>
          <dt>Adjustments</dt>
          <dd data-testid="tax-summary-adjustments">{{ t.adjustments | money: t.homeCurrency }}</dd>
          <dt>Tax liability (tax collected, after adjustments)</dt>
          <dd data-testid="tax-summary-total">
            <span data-testid="tax-liability-total">{{ t.total | money: t.homeCurrency }}</span>
          </dd>
        </dl>
      }
      <app-tax-adjustments (recorded)="summary.reload()" />
    </section>
  `,
})
export class TaxSummaryReport {
  private readonly service = inject(DashboardService);

  private readonly range = signal<{ from: string; to: string } | undefined>(undefined);
export interface TaxSummary {
  from: string;
  to: string;
  homeCurrency: CurrencyCode;
  /** How many invoices the tax came from. */
  invoices: number;
  tax: number;
  /** The levy (second tax). */
  levy: number;
  /** The net of the manual tax adjustments dated within the range. */
  adjustments: number;
  /** The tax, levy and adjustments together. */
  total: number;
}

}

/** An invoice as listed on a client's statement: its project's name and how much is left to pay. */
export interface StatementInvoice extends Omit<ProjectInvoice, 'retention'> {
  projectName: string;
  /** The sales tax and levy on the invoice. */
  tax: number;
}

}

/**
 * A single invoice with the line items it is built from: their subtotal, each of its discounts (a
 * percentage or flat amount) and what they take off together, and the sales tax percentage, the taxable base it is charged on (the taxable
 * lines after the discount, leaving out tax-free ones) and what it adds, and the levy (a second tax)
 * percentage and what it adds on that same base, and any flat surcharge (such as a handling fee) added
 * after tax; its amount is the subtotal less the discount plus the tax plus the levy plus the surcharge.
 */
export interface InvoiceDetail extends Invoice {
  /** The total before tax: the amount less the sales tax and levy. */
  totalExTax: number;
  subtotal: number;
  /** The percentage discounts added up; zero when there are none. */
  discountPct: number;
  /** The flat amount discounts added up (taken off after the percentages); zero when there are none. */
  discountAmount: number;
  /** What all the discounts take off together, before tax. */
  discount: number;
  /** Each discount on the invoice, in the order it was added. */
  discounts: InvoiceDiscount[];
  taxPct: number;
  taxableBase: number;
  tax: number;
  levyPct: number;
  levy: number;
  /** A flat amount (such as a handling fee) added to the total after tax; zero when there is none. */
  surcharge: number;
  /** Whether the prices already include the tax and levy, so they are worked back out rather than added on. */
  taxInclusive: boolean;
  /** Whether the client is tax exempt, so the invoice carries no tax or levy whatever its lines say. */
  taxExempt: boolean;
  /** The overall tax rate that ended up on the invoice: the tax and levy as a percentage of the total before tax. */
  effectiveTaxPct: number;
  /** The percentage taken off when paid early; zero when no early-payment discount is offered. */
  earlyPaymentPct: number;
  /** How many days after being issued it must be paid within to get the early-payment discount: the client's early-payment window; zero when they have none. */
  earlyPaymentDays: number;
  /** Sets the sales tax percentage added to a draft invoice after its discount; zero removes the tax. */
  applyTax(projectId: number, invoiceId: number, taxPct: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/tax`, { taxPct });
  }

  /** Sets the levy (second tax) percentage added to a draft invoice on top of its sales tax; zero removes the levy. */
  applyLevy(projectId: number, invoiceId: number, levyPct: number): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/levy`, { levyPct });
  }

  /** Sets the flat surcharge (such as a handling fee) added to a draft invoice; zero removes it. */
const FOUR_DECIMALS = /^\d+(\.\d{1,4})?$/;

// A single invoice: the client's tax number when they are tax registered, the things it charges for (description, how many and of what, price each), each line's
// amount, their subtotal, each discount on it (a percentage or a flat amount) as its own negative line and what they take off combined before tax, the taxable amount (leaving out tax-free lines), any
// sales tax added on it after the discount, any levy (a second tax) added on the same base, the effective tax rate
// (the tax and levy as a percentage of the total before tax), any flat surcharge (such as a handling fee, added after tax and
// never taxed), the total before tax, and the final total including both taxes (also shown as the total after tax).
// For a client whose prices already include tax, the tax and levy are instead shown as worked back out of the price; the total is unchanged.
// When the net total comes out under the invoice's minimum charge, the minimum is billed instead and marked as applied.
// A foreign invoice also shows its original amount in the client's currency alongside its total in the home currency, converted at the exchange rate from its issue date.
// It also shows the client's purchase-order number, which can be put on or cleared at any time.
// It also shows the total savings: every line discount and invoice discount added together.
// When an early-payment discount is offered, it also shows the reduced amount to pay if settled within the client's early-payment window.
// Lines, the discounts (set to one, added to, or removed one at a time), the tax rate, the levy rate, the surcharge, the minimum charge and the early-payment discount can be changed while it is a draft.
@Component({
              @if (inv.status === 'DRAFT') {
                <td></td>
              }
            </tr>
            <tr>
              <th scope="row" colspan="5">Taxable amount (excludes tax-free lines)</th>
              <td data-testid="invoice-taxable-base">{{ inv.taxableBase | money: inv.currency }}</td>
              @if (inv.status === 'DRAFT') {
                <td></td>
              }
            </tr>
            <tr>
              <th scope="row" colspan="5" data-testid="invoice-tax-label">
                Tax (<span data-testid="invoice-tax-pct">{{ inv.taxPct | number: '1.0-2' : 'en-US' }}</span>%)@if (inv.taxInclusive) { included}
              </th>
              <td data-testid="invoice-tax">{{ inv.tax | money: inv.currency }}</td>
              @if (inv.status === 'DRAFT') {
                <td></td>
              }
            </tr>
            <tr>
              <th scope="row" colspan="5" data-testid="invoice-tax-levy-label">
                Levy (<span data-testid="invoice-tax-levy-pct">{{ inv.levyPct | number: '1.0-2' : 'en-US' }}</span>%)@if (inv.taxInclusive) { included}
              </th>
              <td data-testid="invoice-tax-levy">{{ inv.levy | money: inv.currency }}</td>
              @if (inv.status === 'DRAFT') {
                <td></td>
              }
            </tr>
            <tr>
              <th scope="row" colspan="5">Surcharge</th>
              <td data-testid="invoice-surcharge">{{ inv.surcharge | money: inv.currency }}</td>
              @if (inv.status === 'DRAFT') {
                <td></td>
              }
            </tr>
            <tr>
              <th scope="row" colspan="5">Effective tax rate (tax and levy as a share of the total before tax)</th>
              <td data-testid="invoice-effective-tax-rate">{{ inv.effectiveTaxPct | number: '1.2-2' : 'en-US' }}%</td>
              @if (inv.status === 'DRAFT') {
                <td></td>
              }
            </tr>
            <tr>
              <th scope="row" colspan="5">Total before tax</th>
              <td data-testid="invoice-total-ex-tax">{{ inv.totalExTax | money: inv.currency }}</td>
            />
            @if (taxInvalid()) {
              <p id="tax-pct-error" role="alert" data-testid="tax-form-pct-error">
                Enter a percentage from 0 to 100 with at most two decimal places.
              </p>
            }
          </div>
          <button type="submit" data-testid="tax-form-submit" [disabled]="taxSaving()">Apply tax</button>
          @if (taxError()) {
            <p role="alert" data-testid="tax-form-error">{{ taxError() }}</p>
          }
        </form>

        <form [formGroup]="levyForm" (ngSubmit)="applyLevy()" data-testid="levy-form" novalidate>
          <h2>Levy</h2>
          <div>
            <label for="levy-pct">Levy percentage added on top of the sales tax</label>
            <input
              id="levy-pct"
              type="number"
              inputmode="decimal"
              min="0"
              max="100"
              step="0.01"
              formControlName="levyPct"
              data-testid="levy-form-pct"
              [attr.aria-invalid]="levyInvalid()"
              [attr.aria-describedby]="levyInvalid() ? 'levy-pct-error' : null"
            />
            @if (levyInvalid()) {
              <p id="levy-pct-error" role="alert" data-testid="levy-form-pct-error">
                Enter a percentage from 0 to 100 with at most two decimal places.
              </p>
            }
          </div>
          <button type="submit" data-testid="levy-form-submit" [disabled]="levySaving()">Apply levy</button>
          @if (levyError()) {
            <p role="alert" data-testid="levy-form-error">{{ levyError() }}</p>
          }
        </form>

        <form [formGroup]="surchargeForm" (ngSubmit)="applySurcharge()" data-testid="surcharge-form" novalidate>
          <h2>Surcharge</h2>
          <div>
            <label for="surcharge-amount">Flat amount added to the total, such as a handling fee</label>
            <input
        this.taxSaving.set(false);
      },
      error: () => {
        this.taxError.set('Could not apply the tax. Please try again.');
        this.taxSaving.set(false);
      },
    });
  }

  protected readonly levySaving = signal(false);
  protected readonly levyError = signal<string | null>(null);

  protected readonly levyForm = this.fb.group({
    levyPct: ['', [Validators.required, Validators.min(0), Validators.max(100), Validators.pattern(TWO_DECIMALS)]],
  });

  // Starts the levy field from the invoice's current rate whenever the invoice loads.
  private readonly syncLevy = effect(() => {
    if (this.invoice.hasValue()) {
      this.levyForm.setValue({ levyPct: String(this.invoice.value().levyPct) });
    }
  });

  protected levyInvalid(): boolean {
    const control = this.levyForm.controls.levyPct;
    return control.invalid && (control.touched || control.dirty);
  }

  protected applyLevy(): void {
    if (this.levyForm.invalid) {
      this.levyForm.markAllAsTouched();
      return;
    }
    this.levySaving.set(true);
    this.levyError.set(null);
    const levyPct = Number(this.levyForm.getRawValue().levyPct);
    this.service.applyLevy(this.projectIdNumber(), Number(this.invoiceId()), levyPct).subscribe({
      next: (updated) => {
        this.invoice.set(updated);
        this.levySaving.set(false);
      },
      error: () => {
        this.levyError.set('Could not apply the levy. Please try again.');
        this.levySaving.set(false);
      },
    });
  }

  protected readonly surchargeSaving = signal(false);
  protected readonly surchargeError = signal<string | null>(null);

